import sys, re, html
from html.parser import HTMLParser
class P(HTMLParser):
    def __init__(self):
        super().__init__(); self.out=[]; self.skip=0
    def handle_starttag(self, tag, attrs):
        if tag in ('script','style','math'): 
            # keep math alttext
            if tag=='math':
                d=dict(attrs); 
                if 'alttext' in d: self.out.append(' '+d['alttext']+' ')
            self.skip+=1
        if tag in ('p','div','tr','h1','h2','h3','h4','h5','h6','li','br','table','figcaption','section'): self.out.append('\n')
        if tag in ('td','th'): self.out.append(' | ')
    def handle_endtag(self, tag):
        if tag in ('script','style','math'): self.skip=max(0,self.skip-1)
    def handle_data(self, d):
        if not self.skip: self.out.append(d)
for src, dst in zip(sys.argv[1::2], sys.argv[2::2]):
    p=P(); p.feed(open(src,encoding='utf-8',errors='replace').read())
    t=''.join(p.out); t=re.sub(r'[ \t]+',' ',t); t=re.sub(r'\n\s*\n+','\n',t)
    open(dst,'w').write(t)
EOF
