keys=['short','title','arxiv','first_version','venue','contribution','limitation','builds_on','problem','skill','draft_source','training','shape','verification','max_draft_len_evaluated','reported_tau','max_batch_evaluated','targets_deep_positions','per_position_analysis','evidence','notes']
ok_ds={'separate small LM','target\'s own layers','parallel heads','AR head on target features','parallel/diffusion drafter','semi-AR / conditioned parallel drafter','lookup / retrieval','n/a',None}
ok_tr={'training-free','trained drafter','distilled / aligned to target','trained on own drafts','built into target training','RL / acceptance-objective','n/a',None}
ok_sh={'chain','static tree','dynamic tree','multi-draft','lattice / path search','adaptive length','n/a',None}
ok_v={'token-wise rejection','greedy match','multi-draft coupling','block / sequence-level','n/a',None}
print('entries',len(d))
for e in d:
    assert list(e.keys())==keys, (e['short'], set(keys)^set(e.keys()))
    assert e['draft_source'] in ok_ds, e['short']; assert e['training'] in ok_tr, e['short']
    assert e['shape'] in ok_sh, e['short']; assert e['verification'] in ok_v, e['short']
    for k in ('max_draft_len_evaluated','max_batch_evaluated'): assert e[k] is None or isinstance(e[k],int), (e['short'],k)
    if e['problem']: assert len(e['problem'].split())<=15, (e['short'], len(e['problem'].split()))
    if e['skill']: assert len(e['skill'].split())<=6, (e['short'], e['skill'])
    for k in ('targets_deep_positions','per_position_analysis'):
        if e[k]: 
            n=len(e[k].split()); 
            if n>22: print('long',e['short'],k,n)
print('schema OK')
" && rm -rf /tmp/lit2026_E_work /tmp/lit2026_E_scripts && ls -la /tmp/lit2026/

